 for(const [name,cat] of newNames){if(!data.products.some(p=>String(p.name).trim().toLowerCase()===name.toLowerCase())){data.products.push({id:Math.max(0,...data.products.map(p=>Number(p.id)||0))+1,name,category:cat,price:0,hpp:0,stock:0,active:false,createdAt:new Date().toISOString()});changed=true}}
