async function shareReceiptWhatsApp(){const s=receiptSale;if(!s)return toast('Struk belum tersedia.');const canvas=await receiptCanvas(s);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)return toast('Gagal membuat gambar struk.');const file=new File([blob],`struk-${String(s.id).replace(/[^a-z0-9_-]/gi,'')}.png`,{type:'image/png'});const text=`Struk ${data.settings.outlet||'OR!ON CORNDOG'}\nNo. transaksi: ${s.id}\nTotal: ${money(s.total)}`;try{if(navigator.canShare&&navigator.canShare({files:[file]})){await navigator.share({files:[file],title:'Struk OR!ON CORNDOG',text});return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);window.open('https://wa.me/?text='+encodeURIComponent(text+'\nGambar struk telah diunduh. Lampirkan file PNG tersebut di WhatsApp.'),'_blank','noopener');toast('Gambar struk diunduh. Lampirkan PNG di WhatsApp.')}catch(err){if(err.name!=='AbortError')toast('Berbagi gambar tidak tersedia. Coba unduh/cetak struk.')}}
function renderMenu(){const q=$("#menu-search").value.toLowerCase(),list=data.products.filter(p=>`${p.name} ${p.category}`.toLowerCase().includes(q));$("#menu-table").innerHTML=`<table><thead><tr><th>Menu</th><th>Kategori</th><th>Harga</th><th>HPP internal</th><th>Stok</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${list.map(p=>`<tr><td>${p.image?`<img class="menu-thumb" src="${p.image}" alt="">`:""} <strong>${esc(p.name)}</strong></td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td>${money(p.hpp)}</td><td>${p.stock}</td><td>${p.active===false?"Nonaktif":"Aktif"}</td><td><div class="table-actions"><button class="mini-btn" data-edit-product="${p.id}">Edit</button><button class="mini-btn" data-toggle-product="${p.id}">${p.active===false?"Aktifkan":"Nonaktif"}</button></div></td></tr>`).join("")}</tbody></table>`;$("#category-list").innerHTML=data.categories.map((c,i)=>`<div class="category-row"><span class="category-name">${esc(c)}</span><div class="category-actions"><button type="button" data-edit-category="${esc(c)}" title="Edit nama kategori">Edit</button><button type="button" data-move-category="${esc(c)}" data-direction="-1" ${i===0?"disabled":""} aria-label="Naikkan kategori" title="Naikkan">↑</button><button type="button" data-move-category="${esc(c)}" data-direction="1" ${i===data.categories.length-1?"disabled":""} aria-label="Turunkan kategori" title="Turunkan">↓</button><button type="button" data-del-category="${esc(c)}" title="Hapus kategori">Hapus</button></div></div>`).join("")||'<div class="empty-state">Belum ada kategori.</div>'}
