function renderSettings(){const s=data.settings;const staffSection=$("#staff-account-section");if(staffSection)staffSection.classList.toggle("hidden",!["owner","admin"].includes(userRole()));$("#setting-outlet").value=s.outlet||"";$("#setting-address").value=s.address||"";$("#setting-phone").value=s.phone||"";$("#setting-footer").value=s.footer||"";$("#setting-low-stock").value=s.lowStock??5}
