function openForm(title,fields,onSave,initial={}){formMode=title;$("#form-title").textContent=title;$("#form-fields").innerHTML=fields.map(f=>{const value=initial[f.name]??f.value??"";let input;if(f.type==="select")input=`<select name="${f.name}" ${f.required===false?"":"required"}>${(f.options||[]).map(o=>`<option value="${esc(o.value)}" ${String(o.value)===String(value)?"selected":""}>${esc(o.label)}</option>`).join("")}</select>`;else if(f.type==="textarea")input=`<textarea name="${f.name}" rows="3" ${f.required===false?"":"required"}>${esc(value)}</textarea>`;else if(f.type==="file")input=`<input name="${f.name}" type="file" accept="image/*" ${f.required===false?"":"required"}><small class="muted">Pilih foto dari HP. Gambar akan diperkecil agar penyimpanan lebih ringan.</small>${initial.image?`<img class="form-image-preview" src="${initial.image}" alt="Pratinjau gambar menu">`:""}`;else input=`<input name="${f.name}" type="${f.type||"text"}" value="${esc(value)}" ${f.min!==undefined?`min="${f.min}"`:""} ${f.step?`step="${f.step}"`:""} ${f.required===false?"":"required"} ${f.placeholder?`placeholder="${esc(f.placeholder)}"`:""}>`;return `<label class="${f.full?"full-field":""}">${esc(f.label)}${input}</label>`}).join("");$("#dynamic-form").onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget),obj=Object.fromEntries(fd.entries());const file=fd.get("image");const finish=()=>{onSave(obj);$("#form-dialog").close()};if(file instanceof File&&file.size){if(!file.type.startsWith("image/"))return toast("File harus berupa gambar.");const reader=new FileReader();reader.onload=()=>{const im=new Image();im.onload=()=>{const canvas=document.createElement("canvas"),max=700,scale=Math.min(1,max/Math.max(im.width,im.height));canvas.width=Math.round(im.width*scale);canvas.height=Math.round(im.height*scale);canvas.getContext("2d").drawImage(im,0,0,canvas.width,canvas.height);obj.image=canvas.toDataURL("image/jpeg",.78);finish()};im.onerror=()=>toast("Gambar tidak dapat dibaca.");im.src=reader.result};reader.readAsDataURL(file)}else finish()};$("#form-dialog").showModal()}
function productFields(p={}){return[{name:"name",label:"Nama menu",value:p.name||"",full:true},{name:"category",label:"Kategori",type:"select",value:p.category||data.categories[0],options:data.categories.map(c=>({value:c,label:c}))},{name:"price",label:"Harga jual (Rp)",type:"number",min:0,value:p.price??0},{name:"hpp",label:"HPP internal (Rp)",type:"number",min:0,value:p.hpp??0},{name:"stock",label:"Stok awal / tersedia",type:"number",min:0,value:p.stock??0},{name:"image",label:"Gambar menu (opsional)",type:"file",required:false,full:true},{name:"removeImage",label:"Hapus gambar tersimpan? ketik YA jika ingin menghapus",required:false,full:true,value:""}]}
