 const t={...POS_THEME_DEFAULTS,...(data.settings?.posTheme||{})},root=document.documentElement;
 root.style.setProperty("--cream",t.pageBg);root.style.setProperty("--paper",t.cardBg);root.style.setProperty("--wine",t.primary);root.style.setProperty("--wine2",t.primary);root.style.setProperty("--ink",t.fontColor);root.style.setProperty("--pos-sidebar-bg",t.sidebarBg);root.style.setProperty("--pos-bubble-bg",t.bubbleBg);root.style.setProperty("--pos-font-family",t.fontFamily);
